using Captovix;
using System.IO;
using System.Windows;
internal static class Program
{
 static int n;static void Check(bool ok,string label){if(!ok)throw new Exception(label);n++;Console.WriteLine("PASS: "+label);}
 [STAThread] static int Main(){string folder=Path.Combine(Path.GetTempPath(),"Captovix-M4-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);MediaItem? media=null;try{
 var pixels=Enumerable.Repeat((byte)255,640*400*4).ToArray();var image=ImageTransfer.Bitmap(640,400,pixels);var path=Path.Combine(folder,"form.png");ImageTransfer.Save(image,path);media=new(){Id=Guid.NewGuid().ToString("N"),FilePath=path};var session=DocumentStore.Load(media,image,out _);
 var panel=new Annotation{Kind=AnnotationKind.Rectangle,X1=20,Y1=20,X2=280,Y2=180,FillColor="#DDEEFF",FillEnabled=true};var label=new Annotation{Kind=AnnotationKind.Text,TextFrame=true,AutoFitText=false,X1=50,Y1=45,X2=180,Y2=85,Text="Nhãn tiếng Việt",FontSize=20,TextWidth=130};var button=new Annotation{Kind=AnnotationKind.Rectangle,X1=50,Y1=110,X2=160,Y2=150,FillColor="#00AABB",FillEnabled=true};session.Change(d=>d.Annotations.AddRange([panel,label,button]));DocumentStore.Save(media,session,image);var old=File.ReadAllBytes(DocumentStore.EditPath(media.Id));string inner="",outer="";session.Change(d=>{inner=AnnotationEditing.Group(d,[button.Id,label.Id])!;outer=AnnotationEditing.Group(d,[panel.Id,label.Id])!;});
 var surface=new EditorSurface{Tool=EditorTool.Select,SnapEnabled=false};surface.Load(image,session);surface.SelectIds([panel.Id]);surface.PointerDown(new(240,130));surface.PointerMove(new(300,170));surface.PointerUp(new(300,170));Check(panel.X1==80&&label.X1==110&&button.X1==110,"Native drag moves whole panel, label and button by same delta");Check(surface.SelectedIds.Count==3,"Canvas selects entire nested hierarchy");
 surface.SelectInGroup([label.Id],label.Id,inner);var oldPanel=panel.X1;var oldButton=button.X1;surface.PointerDown(new(145,100));surface.PointerMove(new(165,110));surface.PointerUp(new(165,110));Check(label.X1==130&&panel.X1==oldPanel&&button.X1==oldButton,"Scoped native drag changes label only");
 var state=session.Document.Serialize();var rendered=ImageTransfer.Bgra(surface.Flatten());DocumentStore.Save(media,session,image);Check(File.ReadAllBytes(DocumentStore.EditPath(media.Id)+".pre-v1.41.bak").SequenceEqual(old),"Schema21 save backs up old sidecar unchanged");var reopened=DocumentStore.Load(media,image,out var warning);Check(warning==null&&reopened.Document.Version==21,"Nested layout reopens schema21");Check(ImageTransfer.Bgra(EditorRenderer.Render(image,reopened.Document)).SequenceEqual(rendered),"Save/reopen retains exact rendered layout");
 string project=Path.Combine(folder,"layout.captovix");CompositionProject.Save(project,ImageTransfer.Png(image),session.Document);var loaded=CompositionProject.Load(project);Check(loaded.Document.Annotations.First(a=>a.Id==label.Id).GroupPath!.SequenceEqual([outer]),"Portable project retains parent-child relation");
 surface.SelectParentGroup();Check(surface.SelectedIds.Count==2&&surface.GroupScope==outer,"Select parent picks inner control group");surface.SelectParentGroup();Check(surface.SelectedIds.Count==3&&surface.GroupScope==null,"Select parent again picks whole panel");
 session.Undo();surface.Refresh();session.Redo();surface.Refresh();Check(session.Document.Serialize()==state,"Gesture Undo/Redo restores exact nested layout");Console.WriteLine(n+" M4 Windows gesture/render/persistence checks passed; physical popup/DPI acceptance separate.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{StaImageWorker.Stop();if(media!=null){foreach(var suffix in new[]{"",".bak",".pre-v1.13.bak",".pre-v1.38.bak",".pre-v1.39.bak",".pre-v1.40.bak",".pre-v1.41.bak"})File.Delete(DocumentStore.EditPath(media.Id)+suffix);File.Delete(DocumentStore.ThumbnailPath(media.Id));}Directory.Delete(folder,true);}}
}
